// GENERATED by scripts/build-worker.mjs from worker/src/index.js and shared/rules.js.
// Paste this whole file into the Cloudflare Worker editor. Edit the sources, not this file.

// ===== shared/rules.js =====
// Shared rules for Al's Playground stage times.
// Used by the results page, the submit page, the Worker and the build script,
// so a time is parsed, checked, ranked and formatted the same way everywhere.
// Plain ES module, no dependencies.

const SCHEMA_VERSION = 1;

// ---------------------------------------------------------------- times

const TIME_RE = /^(\d{1,2}):([0-5]\d)[.,](\d{1,3})$/;

/**
 * Parse a typed time like "6:48.034" into whole milliseconds.
 * Accepts a leading zero on minutes, a comma decimal, and 1–3 decimals
 * (padded: "6:48.5" is 6:48.500). Decimals are required.
 * Returns { ok: true, ms } or { ok: false, error }.
 */
function parseTime(input) {
  const s = String(input ?? '').trim();
  if (s === '') return { ok: false, error: 'Enter a time, like 8:31.274' };
  const m = TIME_RE.exec(s);
  if (!m) return { ok: false, error: 'Use minutes:seconds.thousandths, like 8:31.274' };
  const minutes = Number(m[1]);
  const seconds = Number(m[2]);
  const millis = Number(m[3].padEnd(3, '0'));
  return { ok: true, ms: (minutes * 60 + seconds) * 1000 + millis };
}

/** 408034 -> "6:48.034" (stage, checkpoint and sector times). */
function formatTime(ms) {
  const total = Math.max(0, Math.round(ms));
  const minutes = Math.floor(total / 60000);
  const seconds = Math.floor((total % 60000) / 1000);
  const millis = total % 1000;
  return `${minutes}:${String(seconds).padStart(2, '0')}.${String(millis).padStart(3, '0')}`;
}

/**
 * Gap in RSF style: under a minute "02.466" (two-digit seconds, no sign),
 * a minute or more "1:04.086".
 */
function formatDiff(ms) {
  const total = Math.max(0, Math.round(ms));
  if (total < 60000) {
    const seconds = Math.floor(total / 1000);
    const millis = total % 1000;
    return `${String(seconds).padStart(2, '0')}.${String(millis).padStart(3, '0')}`;
  }
  return formatTime(total);
}

/** Readback shown under a time box: 408034 -> "6 min 48.034 s". */
function formatReadback(ms) {
  const minutes = Math.floor(ms / 60000);
  const rest = ms - minutes * 60000;
  const sec = (rest / 1000).toFixed(3);
  return `${minutes} min ${sec} s`;
}

// ---------------------------------------------------------------- names

/** Collapse runs of whitespace and trim. */
function cleanName(name) {
  return String(name ?? '').replace(/\s+/g, ' ').trim();
}

/** Key used to treat "Jane Driver" and "jane  driver" as the same driver. */
function driverKey(name) {
  return cleanName(name).normalize('NFKC').toLocaleLowerCase('en-US');
}

const NAME_RE = /^[\p{L}\p{M}\p{N} .\-_']+$/u;

function validateDriver(name) {
  const n = cleanName(name);
  if (n.length < 2 || n.length > 32) return 'Name must be 2–32 characters.';
  if (/https?:|www\.|[<>]/i.test(n)) return 'Names can’t contain links or < >.';
  if (!NAME_RE.test(n)) return 'Use letters, numbers, spaces and . - _ \' only.';
  return null;
}

// ---------------------------------------------------------------- whole run

/**
 * Check one run's times against each other and the stage bounds.
 * times: { cp1_ms, cp2_ms, finish_ms }; stage: stage.json.
 * Returns a list of { field, message }; empty means valid.
 */
function checkTimes(times, stage) {
  const errors = [];
  const { cp1_ms, cp2_ms, finish_ms } = times;
  if (!(cp1_ms < cp2_ms)) errors.push({ field: 'cp2', message: 'Checkpoint 2 must be later than Checkpoint 1.' });
  if (!(cp2_ms < finish_ms)) errors.push({ field: 'finish', message: 'Finish must be later than Checkpoint 2.' });
  if (stage) {
    if (finish_ms < stage.min_finish_ms) {
      errors.push({ field: 'finish', message: 'That’s faster than looks possible on this stage. Check the digits.' });
    } else if (finish_ms > stage.max_finish_ms) {
      errors.push({ field: 'finish', message: `That’s longer than ${formatTime(stage.max_finish_ms)}. Check the digits.` });
    }
  }
  return errors;
}

/**
 * Schema check for a stored submission file (used by the build).
 * Returns null if valid, otherwise a short reason.
 */
function checkStoredRun(run, carIds, stage) {
  if (!run || typeof run !== 'object') return 'not an object';
  if (run.schema !== SCHEMA_VERSION) return `schema must be ${SCHEMA_VERSION}`;
  if (typeof run.id !== 'string' || !/^[a-z0-9]{4,16}$/.test(run.id)) return 'bad id';
  const nameErr = validateDriver(run.driver);
  if (nameErr) return `driver: ${nameErr}`;
  if (!carIds.has(run.car_id)) return `unknown car_id "${run.car_id}"`;
  if (typeof run.car_name !== 'string' || !run.car_name) return 'missing car_name';
  for (const k of ['cp1_ms', 'cp2_ms', 'finish_ms']) {
    if (k === 'cp2_ms' && run[k] === null) continue;        // stored real results only: no checkpoint 2 time
    if (!Number.isInteger(run[k]) || run[k] <= 0) return `${k} must be a positive whole number`;
  }
  const timeErr = run.cp2_ms === null
    ? checkTimes({ ...run, cp2_ms: (run.cp1_ms + run.finish_ms) / 2 }, stage)
    : checkTimes(run, stage);
  if (timeErr.length) return timeErr[0].message;
  if (typeof run.uploaded_at !== 'string' || Number.isNaN(Date.parse(run.uploaded_at))) return 'bad uploaded_at';
  if (run.screenshot !== null && run.screenshot !== undefined && typeof run.screenshot !== 'string') return 'bad screenshot';
  if (!['published', 'hidden'].includes(run.status)) return 'status must be "published" or "hidden"';
  if (run.label !== undefined && (typeof run.label !== 'string' || run.label.length > 20)) return 'label must be text, 20 characters at most';
  if (run.note !== undefined && (typeof run.note !== 'string' || run.note.length > 200)) return 'note must be text, 200 characters at most';
  return null;
}

/**
 * Check a submission exactly as typed on the form. Used by the submit page
 * (live, before sending) and again by the Worker (before saving).
 *
 * input:   { driver, car_id, cp1, cp2, finish, consent }  (times as typed)
 * context: { stage, cars: cars.json, existing: published runs (optional) }
 * Returns  { errors: [{ field, message }], value } where value is the cleaned
 *          run (driver, car_id, car_name, *_ms, entered) when errors is empty.
 */
function validateSubmission(input, { stage, cars, existing = [] }) {
  const errors = [];
  const add = (field, message) => errors.push({ field, message });
  const src = input || {};

  const driver = cleanName(src.driver);
  const driverErr = validateDriver(driver);
  if (driverErr) add('driver', driverErr);

  const car = (cars?.cars || []).find((c) => c.id === src.car_id && c.active !== false);
  if (!car) add('car', 'Choose a car from the list.');

  const times = {};
  for (const field of ['cp1', 'cp2', 'finish']) {
    const p = parseTime(src[field]);
    if (p.ok) times[field] = p.ms;
    else add(field, p.error);
  }
  if ('cp1' in times && 'cp2' in times && 'finish' in times) {
    for (const e of checkTimes({ cp1_ms: times.cp1, cp2_ms: times.cp2, finish_ms: times.finish }, stage)) add(e.field, e.message);
  }

  if (src.consent !== true) add('consent', 'Tick the box to agree your name and screenshot are shown publicly.');

  if (!errors.length) {
    const key = driverKey(driver);
    const dup = existing.some((r) => driverKey(r.driver) === key && r.car_id === car.id && r.finish_ms === times.finish);
    if (dup) add('finish', 'This time is already on the board.');
  }

  if (errors.length) return { errors, value: null };
  return {
    errors,
    value: {
      driver,
      car_id: car.id,
      car_name: car.name,
      cp1_ms: times.cp1,
      cp2_ms: times.cp2,
      finish_ms: times.finish,
      entered: { cp1: String(src.cp1).trim(), cp2: String(src.cp2).trim(), finish: String(src.finish).trim() },
    },
  };
}

// ---------------------------------------------------------------- ranking

function byFinishThenUpload(a, b) {
  if (a.finish_ms !== b.finish_ms) return a.finish_ms - b.finish_ms;
  return Date.parse(a.uploaded_at) - Date.parse(b.uploaded_at);
}

/**
 * Rank runs for display.
 * runs:    published runs (from results.json)
 * options: { view: 'best' | 'all', group: '' | group name, carGroup: Map car_id -> group }
 *
 * - The class filter is applied first, so "best per driver" in Group A is
 *   each driver's best Group A run.
 * - Best per driver keeps each driver's fastest run (earliest upload on a tie).
 * - Sorted by finish, ties by upload time. Competition ranking: 1, 2, 2, 4.
 * - Diffs use finish only. Leader shows 0 in both; a tie shows 0 Diff. Prev.
 *
 * Returns { rows, fastestCp1, fastestCp2, fastestSectors, runsByDriver }.
 */
function rankRuns(runs, options = {}) {
  const { view = 'best', group = '', carGroup = new Map(), source = '' } = options;

  // source: '' all runs, 'virtual' RBR runs only, 'real' curated real-world results only (see runTag)
  const inSource = source ? runs.filter((r) => runTag(r).kind === source) : runs;

  const runsByDriver = new Map();
  for (const r of inSource) {
    const k = driverKey(r.driver);
    runsByDriver.set(k, (runsByDriver.get(k) || 0) + 1);
  }

  let pool = group ? inSource.filter((r) => carGroup.get(r.car_id) === group) : inSource.slice();

  if (view === 'best') {
    const best = new Map();
    for (const r of pool) {
      const k = driverKey(r.driver);
      const cur = best.get(k);
      if (!cur || byFinishThenUpload(r, cur) < 0) best.set(k, r);
    }
    pool = [...best.values()];
  }

  pool.sort(byFinishThenUpload);

  const rows = [];
  for (let i = 0; i < pool.length; i++) {
    const run = pool[i];
    const prev = i > 0 ? rows[i - 1] : null;
    const pos = prev && prev.run.finish_ms === run.finish_ms ? prev.pos : i + 1;
    rows.push({
      run,
      pos,
      diffPrev: prev ? run.finish_ms - prev.run.finish_ms : 0,
      diffFirst: i > 0 ? run.finish_ms - pool[0].finish_ms : 0,
      sectors: sectorsOf(run),
      driverRuns: runsByDriver.get(driverKey(run.driver)) || 1,
    });
  }

  const min = (f) => {
    const v = rows.map(f).filter((x) => x !== null && x !== undefined);
    return v.length ? Math.min(...v) : null;
  };
  return {
    rows,
    fastestCp1: min((x) => x.run.cp1_ms),
    fastestCp2: min((x) => x.run.cp2_ms),
    fastestSectors: [0, 1, 2].map((s) => min((x) => x.sectors[s])),
  };
}

/** Sector times from cumulative checkpoints: [S1, S2, S3]. */
function sectorsOf(run) {
  if (run.cp2_ms === null || run.cp2_ms === undefined) return [run.cp1_ms, null, null];
  return [run.cp1_ms, run.cp2_ms - run.cp1_ms, run.finish_ms - run.cp2_ms];
}

// ---------------------------------------------------------------- timestamps

const fmtCache = new Map();
function zoneFormatter(timeZone) {
  if (!fmtCache.has(timeZone)) {
    fmtCache.set(timeZone, new Intl.DateTimeFormat('en-US', {
      timeZone,
      year: 'numeric', month: '2-digit', day: '2-digit',
      hour: '2-digit', minute: '2-digit', second: '2-digit',
      hourCycle: 'h23', timeZoneName: 'short',
    }));
  }
  return fmtCache.get(timeZone);
}

/**
 * Show a stored UTC timestamp in a fixed zone (US Central by default).
 * Returns { date: "2026-10-02", time: "16:05:33", zone: "CDT",
 *           offset: "UTC−5", utc: "21:05:33 UTC" }.
 */
function zonedStamp(iso, timeZone = 'America/Chicago') {
  const d = new Date(iso);
  const parts = Object.fromEntries(zoneFormatter(timeZone).formatToParts(d).map((p) => [p.type, p.value]));
  const date = `${parts.year}-${parts.month}-${parts.day}`;
  const time = `${parts.hour}:${parts.minute}:${parts.second}`;
  const asUtc = Date.UTC(+parts.year, +parts.month - 1, +parts.day, +parts.hour, +parts.minute, +parts.second);
  const offsetH = Math.round((asUtc - Math.floor(d.getTime() / 1000) * 1000) / 3600000);
  const offset = offsetH === 0 ? 'UTC' : `UTC${offsetH < 0 ? '−' : '+'}${Math.abs(offsetH)}`;
  const utc = d.toISOString().slice(11, 19) + ' UTC';
  return { date, time, zone: parts.timeZoneName, offset, utc };
}

/**
 * The tag shown beside a driver's name. Curated real-world times carry their own
 * label (e.g. "LSPR 2024"); every other run is a virtual one and is tagged
 * "RBR <year>", the year it was uploaded in the display time zone.
 * Returns { text, kind } with kind "virtual" (RBR runs) or "real".
 */
function runTag(run, timeZone = 'America/Chicago') {
  const text = run.label || `RBR ${zonedStamp(run.uploaded_at, timeZone).date.slice(0, 4)}`;
  return { text, kind: /^RBR\b/.test(text) ? 'virtual' : 'real' };
}

// ---------------------------------------------------------------- real-world comparison

/** The real event a curated run came from, e.g. "SS1" / "SS10" (from its note), or null. */
function realStage(run) {
  if (runTag(run).kind !== 'real') return null;
  const m = /LSPR 2024 (SS\d+)/.exec(run.note || '');
  return m ? m[1] : null;
}

/**
 * Where a finish time would have placed among the real results, per real stage.
 * Returns [{ stage: 'SS1', place, of, faster: run|null, slower: run|null }] in stage order,
 * where faster / slower are the real runs just ahead of / just behind that time.
 */
function realPlacings(finishMs, runs) {
  const byStage = new Map();
  for (const r of runs) {
    const s = realStage(r);
    if (!s) continue;
    if (!byStage.has(s)) byStage.set(s, []);
    byStage.get(s).push(r);
  }
  const num = (s) => Number(s.replace(/\D/g, ''));
  return [...byStage.keys()].sort((a, b) => num(a) - num(b)).map((stage) => {
    const list = byStage.get(stage).slice().sort((a, b) => a.finish_ms - b.finish_ms);
    const ahead = list.filter((r) => r.finish_ms < finishMs);
    return {
      stage,
      place: ahead.length + 1,
      of: list.length,
      faster: ahead.length ? ahead[ahead.length - 1] : null,
      slower: list.find((r) => r.finish_ms >= finishMs) || null,
    };
  });
}

/**
 * Theoretical best: the fastest sector 1, 2 and 3 across the given rows (any runs), added up.
 * Returns { total, parts: [{ ms, run }] x3 } or null when a sector has no time.
 */
function theoreticalBest(rows) {
  const parts = [0, 1, 2].map((s) => {
    let best = null;
    for (const row of rows) {
      const t = row.sectors[s];
      if (t === null || t === undefined) continue;
      if (!best || t < best.ms || (t === best.ms && Date.parse(row.run.uploaded_at) < Date.parse(best.run.uploaded_at))) best = { ms: t, run: row.run };
    }
    return best;
  });
  if (parts.some((p) => !p)) return null;
  return { total: parts.reduce((a, p) => a + p.ms, 0), parts };
}

// ===== worker/src/index.js =====
// Al's Playground submissions Worker (Cloudflare Workers, free plan).
//
// POST /submit  checks one time and, if it's good, commits it to the repo as a
//               new file. It never edits or deletes anything that exists.
// GET  /status  { open: true | false } so the form can say when submissions are closed.
//
// Settings (Cloudflare dashboard → the Worker → Settings → Variables and Secrets):
//   GITHUB_TOKEN       secret  fine-grained token, this repo only, Contents read/write
//   TURNSTILE_SECRET   secret  the Turnstile widget's secret key
//   HASH_SALT          secret  any long random text (used to hash IPs for rate limits)
//   SUBMISSIONS_OPEN   text    "true" to accept times, anything else closes the form
//   DISCORD_WEBHOOK    secret  optional: post each new time to a Discord channel
// Binding:
//   RATE               KV namespace for rate limits and double-submit protection
// Defaults below (REPO, SITE_URL, ...) can be overridden with text variables of the same name.


const DEFAULTS = {
  REPO: 'Hackinator07/als-playground',
  BRANCH: 'main',
  SITE_URL: 'https://hackinator07.github.io/als-playground',
  ALLOWED_ORIGINS: 'https://hackinator07.github.io',
  TURNSTILE_HOSTNAME: 'hackinator07.github.io',
};
const MAX_BODY = 1_000_000;          // bytes; the screenshot is capped at 600 KB before base64
const MAX_IMAGE = 600 * 1024;
const LIMITS = { perHour: 5, perDay: 15, globalPerDay: 200 };

const cfg = (env, k) => (env[k] !== undefined && env[k] !== '' ? env[k] : DEFAULTS[k]);

// ------------------------------------------------------------ entry

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    const origin = request.headers.get('origin') || '';
    const allowed = cfg(env, 'ALLOWED_ORIGINS').split(',').map((s) => s.trim()).filter(Boolean);
    const cors = {
      'access-control-allow-origin': allowed.includes(origin) ? origin : allowed[0],
      'access-control-allow-methods': 'GET, POST, OPTIONS',
      'access-control-allow-headers': 'content-type',
      'access-control-max-age': '86400',
      vary: 'origin',
    };
    const reply = (status, body) => new Response(JSON.stringify(body), {
      status, headers: { 'content-type': 'application/json; charset=utf-8', ...cors },
    });

    if (request.method === 'OPTIONS') return new Response(null, { status: 204, headers: cors });
    if (request.method === 'GET' && url.pathname.replace(/\/+$/, '') === '/status') {
      return reply(200, { open: env.SUBMISSIONS_OPEN === 'true' });
    }
    if (request.method !== 'POST' || !['/', '/submit'].includes(url.pathname.replace(/\/+$/, '') || '/')) {
      return reply(404, { ok: false, message: 'Not found.' });
    }
    if (!allowed.includes(origin)) return reply(403, { ok: false, message: 'Submit times from the stage times page.' });

    try {
      return await handleSubmit(request, env, ctx, reply);
    } catch (err) {
      console.error('submit failed', err && err.stack || err);
      return reply(500, { ok: false, message: 'Something went wrong on our side. Try again in a minute.' });
    }
  },
};

// ------------------------------------------------------------ submit

async function handleSubmit(request, env, ctx, reply) {
  if (env.SUBMISSIONS_OPEN !== 'true') return reply(503, { ok: false, message: 'Submissions are closed right now.' });
  if (!env.GITHUB_TOKEN || !env.TURNSTILE_SECRET) return reply(503, { ok: false, message: 'Submissions aren’t set up yet.' });

  const declared = Number(request.headers.get('content-length') || 0);
  if (declared > MAX_BODY) return reply(413, { ok: false, message: 'That submission is too large. Use a smaller screenshot.' });
  const text = await request.text();
  if (text.length > MAX_BODY) return reply(413, { ok: false, message: 'That submission is too large. Use a smaller screenshot.' });
  let body;
  try { body = JSON.parse(text); } catch { return reply(400, { ok: false, message: 'That didn’t look like a submission.' }); }
  if (!body || typeof body !== 'object') return reply(400, { ok: false, message: 'That didn’t look like a submission.' });

  // Honeypot: a hidden field people never see. Bots fill it in.
  if (body.website) return reply(400, { ok: false, message: 'That didn’t look like a submission.' });

  const ip = request.headers.get('cf-connecting-ip') || '';
  const ts = await verifyTurnstile(env, body.turnstile, ip);
  if (!ts.ok) return reply(403, { ok: false, errors: [{ field: 'turnstile', message: 'The bot check didn’t pass. Try it again.' }] });

  const ipKey = await sha(`${env.HASH_SALT || ''}|${ip}`);
  const limited = await rateLimited(env, ipKey);
  if (limited) return reply(429, { ok: false, message: limited });

  const site = cfg(env, 'SITE_URL').replace(/\/+$/, '');
  const [stage, cars, results] = await Promise.all([
    getJson(`${site}/data/stage.json`), getJson(`${site}/data/cars.json`), getJson(`${site}/results.json`).catch(() => ({ runs: [] })),
  ]);

  const { errors, value } = validateSubmission(body, { stage, cars, existing: results.runs || [] });
  if (errors.length) return reply(400, { ok: false, errors });

  const image = checkImage(body.screenshot);
  if (image.error) return reply(400, { ok: false, errors: [{ field: 'shot', message: image.error }] });

  // Double-submit guard: the board can lag a minute behind, so remember recent saves too.
  const dupKey = `dup:${await sha(`${cleanName(value.driver).toLowerCase()}|${value.car_id}|${value.finish_ms}`)}`;
  if (env.RATE && await env.RATE.get(dupKey)) {
    return reply(400, { ok: false, errors: [{ field: 'finish', message: 'This time is already on the board.' }] });
  }

  const now = new Date();
  const id = randomId();
  const year = now.getUTCFullYear();
  const stamp = now.toISOString().replace(/\.\d+Z$/, 'Z').replace(/:/g, ''); // 2026-10-02T231000Z
  const shotPath = image.data ? `screenshots/${year}/${id}.${image.ext}` : null;
  const record = {
    schema: 1,
    id,
    stage: stage.id || 'als-playground',
    ...value,
    uploaded_at: now.toISOString(),
    screenshot: shotPath,
    status: 'published',
  };
  const files = [{ path: `data/submissions/${year}/${stamp}_${id}.json`, content: JSON.stringify(record, null, 2) + '\n', encoding: 'utf-8' }];
  if (shotPath) files.push({ path: shotPath, content: image.data, encoding: 'base64' });

  await commitFiles(env, files, `New time: ${value.driver}, ${formatTime(value.finish_ms)} (${value.car_name})`);

  if (env.RATE) {
    ctx.waitUntil(Promise.all([
      env.RATE.put(dupKey, '1', { expirationTtl: 86400 }),
      bump(env, `h:${ipKey}:${hourBucket(now)}`, 3600),
      bump(env, `d:${ipKey}:${dayBucket(now)}`, 86400),
      bump(env, `g:${dayBucket(now)}`, 86400),
    ]));
  }
  if (env.DISCORD_WEBHOOK) ctx.waitUntil(notifyDiscord(env, record).catch(() => {}));

  return reply(200, { ok: true, id });
}

// ------------------------------------------------------------ checks

async function verifyTurnstile(env, token, ip) {
  if (typeof token !== 'string' || !token || token.length > 2048) return { ok: false };
  const form = new FormData();
  form.append('secret', env.TURNSTILE_SECRET);
  form.append('response', token);
  if (ip) form.append('remoteip', ip);
  const res = await fetch('https://challenges.cloudflare.com/turnstile/v0/siteverify', { method: 'POST', body: form });
  const out = await res.json().catch(() => ({}));
  if (!out.success) return { ok: false };
  const host = cfg(env, 'TURNSTILE_HOSTNAME');
  if (host && out.hostname && out.hostname !== host) return { ok: false };
  return { ok: true };
}

/** Accepts { type: 'webp' | 'jpeg', data: base64 } or null. Only the first bytes are decoded. */
function checkImage(shot) {
  if (shot === null || shot === undefined) return { data: null };
  if (typeof shot !== 'object' || typeof shot.data !== 'string') return { error: 'That screenshot couldn’t be read. Try another image.' };
  const ext = shot.type === 'webp' ? 'webp' : shot.type === 'jpeg' ? 'jpg' : null;
  if (!ext) return { error: 'Use a PNG, JPG or WebP image.' };
  const data = shot.data.replace(/\s+/g, '');
  if (!/^[A-Za-z0-9+/]+={0,2}$/.test(data)) return { error: 'That screenshot couldn’t be read. Try another image.' };
  const bytes = Math.floor((data.length * 3) / 4) - (data.endsWith('==') ? 2 : data.endsWith('=') ? 1 : 0);
  if (bytes > MAX_IMAGE) return { error: 'That screenshot is too large. Crop it and try again.' };
  const head = atob(data.slice(0, 16));
  const okSig = ext === 'webp'
    ? head.slice(0, 4) === 'RIFF' && head.slice(8, 12) === 'WEBP'
    : head.charCodeAt(0) === 0xff && head.charCodeAt(1) === 0xd8 && head.charCodeAt(2) === 0xff;
  if (!okSig) return { error: 'That file isn’t the image it says it is. Try another screenshot.' };
  return { data, ext };
}

async function rateLimited(env, ipKey) {
  if (!env.RATE) return null;
  const now = new Date();
  const [h, d, g] = await Promise.all([
    env.RATE.get(`h:${ipKey}:${hourBucket(now)}`),
    env.RATE.get(`d:${ipKey}:${dayBucket(now)}`),
    env.RATE.get(`g:${dayBucket(now)}`),
  ]);
  if (Number(g || 0) >= LIMITS.globalPerDay) return 'The board has had a lot of times today. Try again tomorrow.';
  if (Number(h || 0) >= LIMITS.perHour) return 'That’s a lot of times in an hour. Try again later.';
  if (Number(d || 0) >= LIMITS.perDay) return 'That’s the most times you can post today. Try again tomorrow.';
  return null;
}

async function bump(env, key, ttl) {
  const n = Number((await env.RATE.get(key)) || 0) + 1;
  await env.RATE.put(key, String(n), { expirationTtl: Math.max(60, ttl) });
}

const hourBucket = (d) => d.toISOString().slice(0, 13);
const dayBucket = (d) => d.toISOString().slice(0, 10);

// ------------------------------------------------------------ GitHub

function gh(env, path, init = {}) {
  return fetch(`https://api.github.com/repos/${cfg(env, 'REPO')}${path}`, {
    ...init,
    headers: {
      authorization: `Bearer ${env.GITHUB_TOKEN}`,
      accept: 'application/vnd.github+json',
      'x-github-api-version': '2022-11-28',
      'user-agent': 'als-playground-submit',
      ...(init.body ? { 'content-type': 'application/json' } : {}),
    },
  });
}

async function ghJson(env, path, init) {
  const res = await gh(env, path, init);
  if (!res.ok) {
    const err = new Error(`GitHub ${init?.method || 'GET'} ${path}: ${res.status} ${await res.text().catch(() => '')}`);
    err.status = res.status;
    throw err;
  }
  return res.json();
}

/** One commit with all files. New paths only; retries once if main moved meanwhile. */
async function commitFiles(env, files, message) {
  const branch = cfg(env, 'BRANCH');
  for (let attempt = 0; attempt < 2; attempt++) {
    const ref = await ghJson(env, `/git/ref/heads/${branch}`);
    const head = ref.object.sha;
    const commit = await ghJson(env, `/git/commits/${head}`);
    const tree = await ghJson(env, '/git/trees', {
      method: 'POST',
      body: JSON.stringify({
        base_tree: commit.tree.sha,
        tree: await Promise.all(files.map(async (f) => {
          const blob = await ghJson(env, '/git/blobs', { method: 'POST', body: JSON.stringify({ content: f.content, encoding: f.encoding }) });
          return { path: f.path, mode: '100644', type: 'blob', sha: blob.sha };
        })),
      }),
    });
    const created = await ghJson(env, '/git/commits', {
      method: 'POST',
      body: JSON.stringify({ message, tree: tree.sha, parents: [head] }),
    });
    const res = await gh(env, `/git/refs/heads/${branch}`, { method: 'PATCH', body: JSON.stringify({ sha: created.sha, force: false }) });
    if (res.ok) return created.sha;
    if (res.status !== 422 || attempt === 1) throw new Error(`GitHub ref update: ${res.status} ${await res.text().catch(() => '')}`);
  }
}

// ------------------------------------------------------------ helpers

async function getJson(url) {
  const res = await fetch(url, { cf: { cacheTtl: 60 } });
  if (!res.ok) throw new Error(`${url}: ${res.status}`);
  return res.json();
}

async function sha(text) {
  const buf = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(text));
  return [...new Uint8Array(buf)].slice(0, 12).map((b) => b.toString(16).padStart(2, '0')).join('');
}

function randomId() {
  const bytes = crypto.getRandomValues(new Uint8Array(8));
  return [...bytes].map((b) => 'abcdefghijklmnopqrstuvwxyz0123456789'[b % 36]).join('');
}

async function notifyDiscord(env, r) {
  await fetch(env.DISCORD_WEBHOOK, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({
      content: `New time on Al's Playground: **${r.driver}**, ${formatTime(r.finish_ms)} in the ${r.car_name}${r.screenshot ? ' (with screenshot)' : ''}`,
      allowed_mentions: { parse: [] },
    }),
  });
}
